export function buscaBinaria(valores, alvo) {
  let inicio = 0;
  let fim = valores.length;
  while (inicio < fim) {
    const meio = Math.floor((inicio + fim) / 2);
    if (valores[meio] < alvo) inicio = meio + 1;
    else fim = meio;
  }
  return inicio < valores.length && valores[inicio] === alvo ? inicio : -1;
}

