}

import { LIMITE_PADRAO_CENTAVOS, dentroDoLimite } from "../domain/limite.js";

export function gerarRelatorio(repositorio, limiteCentavos = LIMITE_PADRAO_CENTAVOS) {
  const pedidos = repositorio.listar();
  const dentro = [];
  const fora = [];
  for (const pedido of pedidos) {
    (dentroDoLimite(pedido.valorCentavos, limiteCentavos) ? dentro : fora).push(pedido.id);
  }
  return { limiteCentavos, total: pedidos.length, dentro, fora };
}

// Regra de negócio: o pedido está dentro do limite quando o valor é menor ou igual ao limite.
export const LIMITE_PADRAO_CENTAVOS = 10_000;

export function dentroDoLimite(valorCentavos, limiteCentavos = LIMITE_PADRAO_CENTAVOS) {
  if (!Number.isSafeInteger(valorCentavos) || !Number.isSafeInteger(limiteCentavos)) {
    throw new RangeError("valores em centavos inteiros");
  }
  return valorCentavos <= limiteCentavos;
}

// Repositório em memória: devolve cópias para que quem chama não altere o estado guardado.
export function criarRepositorioEmMemoria(pedidosIniciais = []) {
  const pedidos = pedidosIniciais.map((pedido) => ({ ...pedido }));
  return {
    listar: () => pedidos.map((pedido) => ({ ...pedido })),
    salvar(pedido) {
      pedidos.push({ ...pedido });
    },
  };
}

